-- Plantillas para los correos que aún no tenían una (V37): recordatorio de
-- actividades, actas y garantías de activos, proyectos, acceso a confidenciales,
-- alertas de seguridad y aprobaciones. NotificationService.notifyConPlantilla
-- las usa si están activas; si no, manda el texto de siempre. ON CONFLICT DO
-- NOTHING: nunca pisa una plantilla que ya exista.
INSERT INTO notification_template (name_template, type_template, subject_template, body_template,
                                   active_template, recipient_rule, recipient_email, icon_template, color_template)
VALUES
  ('TAREA_POR_VENCER', 'TASK', 'Actividad por vencer: [titulo]', '<div style="background:#f3f4f6;padding:32px 16px;"><div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;"><div style="background:#062e86;padding:24px 32px;text-align:center;">[logo]</div><div style="padding:28px 36px 12px;font-family:Arial,Helvetica,sans-serif;color:#374151;"><h2 style="color:#062e86;margin:0 0 18px;">Actividad por vencer</h2><p>Estimado/a <b>[nombre]</b>:</p><p>La actividad <b>[titulo]</b> vence el <b>[fechaFin]</b>.</p><p>Estado actual: [estado].</p><p style="margin:24px 0;text-align:center;"><a href="[urlTicket]" style="background:#062e86;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:8px;font-weight:bold;display:inline-block;">Ver mis actividades</a></p></div><div style="background:#062e86;padding:20px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0;color:#ffffff;font-weight:bold;font-size:14px;">Mesa de Servicios</p><p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;">Servicio de soporte técnico · COAC Magisterio de Pichincha</p><p style="margin:6px 0 0;color:#aec0dd;font-size:11px;">© 2026 COAC Magisterio de Pichincha. Todos los derechos reservados.</p></div></div><p style="max-width:620px;margin:12px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;">Este correo fue generado automáticamente; por favor no responda a este mensaje.</p></div>', TRUE, 'DEFAULT', NULL, 'fa-solid fa-hourglass-half', '#D97706'),
  ('ACTA_ACTIVO', 'ACTIVO', '[asunto]', '<div style="background:#f3f4f6;padding:32px 16px;"><div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;"><div style="background:#062e86;padding:24px 32px;text-align:center;">[logo]</div><div style="padding:28px 36px 12px;font-family:Arial,Helvetica,sans-serif;color:#374151;"><h2 style="color:#062e86;margin:0 0 18px;">[asunto]</h2><p>Estimado/a <b>[nombre]</b>:</p>[mensaje]<p style="margin:24px 0;text-align:center;"><a href="[urlTicket]" style="background:#062e86;color:#ffffff;text-decoration:none;padding:12px 22px;border-radius:8px;font-weight:bold;display:inline-block;">Ver mis equipos</a></p></div><div style="background:#062e86;padding:20px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0;color:#ffffff;font-weight:bold;font-size:14px;">Mesa de Servicios</p><p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;">Servicio de soporte técnico · COAC Magisterio de Pichincha</p><p style="margin:6px 0 0;color:#aec0dd;font-size:11px;">© 2026 COAC Magisterio de Pichincha. Todos los derechos reservados.</p></div></div><p style="max-width:620px;margin:12px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;">Este correo fue generado automáticamente; por favor no responda a este mensaje.</p></div>', TRUE, 'DEFAULT', NULL, 'fa-solid fa-file-signature', '#0E7490'),
